_KIND={'Repro':'reproduction post','Pruning':'pruning post','Tech':'technical dive','Overview':'overview post','YOLO':'YOLO post','MI355X':'MI355X post','Blog':'blog post','Supp':'MLCommons supplement','per dollar':'per dollar'}
def _name(k): return re.sub(r'( v\d+\.\d+)\1$',r'\1',k)
_pair=collections.Counter((m['vendor'],m['round']) for m in SRC.values())
def _title_label(k):
    m=SRC[k]; base=f"{m['vendor']}, {m['round']}"
    if _pair[(m['vendor'],m['round'])]==1: return base
    t=[w for w in _name(k).split() if w not in m['vendor'].split() and not re.fullmatch(r'v\d+\.\d+',w) and w not in m['round'].split()]
    d=' '.join(t); d=_KIND.get(d,d)
    return base+(', '+d if d else '')
_labels=[_title_label(k) for k in SRC]; assert len(set(_labels))==len(_labels),[l for l in _labels if _labels.count(l)>1]
def _latency_excluded(f):   # closed datacenter rows that have an accelerator count and a latency result: build_perchip.py leaves them out because it keeps tokens, samples and queries per second
    n_=0
    for x in json.load(open(os.path.join(HERE,f))):
        n=x['Nodes']*x['a#'] if isinstance(x['a#'],int) else 0
        named=[int(v) for v in re.findall(r'\(x(\d+)\)',x['Accelerator'])]
        if named and sum(named)!=n: n=sum(named)
        ta=x.get('Total Accelerators')
        if isinstance(ta,int) and not isinstance(x['a#'],int): n=ta
        if x['Category']=='closed' and 'datacenter' in x['Suite'] and n>0 and not str(x['Performance_Units']).startswith(('Tokens','Samples','Queries')): n_+=1
    return n_
